import type { ReactNode } from "react";
import { useTranslation } from "react-i18next";
import { Attribution } from "../components/Attribution";
import { ContentVersions } from "../components/ContentVersions";
import { ViewHeading } from "../components/ViewHeading";
import { useNavigation } from "../navigation/context";
import { ViewLink } from "../navigation/ViewLink";
import { useLoadedContent } from "../state/context";

/** Generated by `build.license` in vite.config.ts and served from the same origin. */
const LICENSES_PATH = "/third-party-licenses.txt";

/** What the app is, how values are calculated, sources, disclaimers, and privacy (docs/en/UI_DESIGN.md §3.6). */
export function AboutView() {
  const { t } = useTranslation();
  const { navigated } = useNavigation();
  const { calc } = useLoadedContent();

  return (
    <div className="flex flex-col gap-6">
      <div className="flex flex-wrap items-baseline justify-between gap-2">
        <ViewHeading title={t("nav.views.about")} focusOnMount={navigated} />
        <ViewLink to={{ name: "targets" }} className="text-primary underline">
          {t("nav.toTargets")}
        </ViewLink>
      </div>
      <Section id="about-purpose" title={t("about.purpose.title")}>
        <p className="m-0">{t("about.purpose.body")}</p>
        <p className="m-0">{t("about.purpose.deterministic")}</p>
      </Section>
      <Section id="about-calculation" title={t("about.calculation.title")}>
        <p className="m-0">{t("disclaimer.estimates")}</p>
        <ul className="m-0 flex list-disc flex-col gap-1 pl-6">
          <li>{t("about.calculation.cooking")}</li>
          <li>{t("about.calculation.approximations")}</li>
          <li>{t("about.calculation.ranges")}</li>
          <li>{t("about.calculation.unmeasured")}</li>
        </ul>
        <p className="m-0">{t("disclaimer.strictControl")}</p>
      </Section>
      <Section id="about-source" title={t("about.source.title")}>
        <Attribution />
        <ContentVersions versions={calc} />
      </Section>
      <Section id="about-allergens" title={t("about.allergens.title")}>
        <p className="m-0">{t("disclaimer.allergens")}</p>
        <p className="m-0">{t("about.allergens.unknown")}</p>
      </Section>
      <Section id="about-health" title={t("about.health.title")}>
        <p className="m-0">{t("about.health.notAdvice")}</p>
        <p className="m-0">{t("disclaimer.presetsAreExamples")}</p>
        <p className="m-0">{t("disclaimer.medicalGuidance")}</p>
      </Section>
      <Section id="about-limits" title={t("about.limits.title")}>
        <ul className="m-0 flex list-disc flex-col gap-1 pl-6">
          <li>{t("about.limits.medical")}</li>
          <li>{t("about.limits.allergens")}</li>
          <li>{t("about.limits.accounts")}</li>
          <li>{t("about.limits.ai")}</li>
        </ul>
      </Section>
      <Section id="about-privacy" title={t("about.privacy.title")}>
        <ul className="m-0 flex list-disc flex-col gap-1 pl-6">
          <li>{t("about.privacy.noTracking")}</li>
          <li>{t("about.privacy.storage")}</li>
          <li>{t("about.privacy.memory")}</li>
          <li>{t("about.privacy.shoppingList")}</li>
        </ul>
      </Section>
      <Section id="about-licenses" title={t("about.licenses.title")}>
        <p className="m-0">{t("about.licenses.body")}</p>
        <p className="m-0">
          <a href={LICENSES_PATH} className="text-primary underline">
            {t("about.licenses.link")}
          </a>
        </p>
      </Section>
    </div>
  );
}

function Section({ id, title, children }: { readonly id: string; readonly title: string; readonly children: ReactNode }) {
  return (
    <section aria-labelledby={id} className="flex flex-col gap-2">
      <h2 id={id} className="text-lg font-bold">
        {title}
      </h2>
      {children}
    </section>
  );
}
